mapper.sql:
select em.evaluation_material_id as "evaluationMaterialId", em.evaluation_year as "evaluationYear", em.area_code as "areaCode", em.target_user_id as "targetUserId", em.source_achievement_id as "sourceAchievementId", em.generation_batch_id as "generationBatchId", em.material_status as "materialStatus", em.material_origin as "materialOrigin", coalesce(em.material_snapshot_json ->> 'achievementTitle', concat('평가자료 ', em.evaluation_material_id)) as "achievementTitle" from evaluation_materials em where em.deleted_yn = 'N' and em.material_origin = 'BATCH_GENERATED' and em.material_status <> '평가확정'
and em.evaluation_year = #{criteria.normalizedEvaluationYear}
and em.area_code = #{criteria.normalizedAreaCode}
and em.generation_batch_id = #{criteria.normalizedGenerationBatchId}

mapper.update:
update evaluation_materials em set deleted_yn = 'Y', material_status = '삭제', delete_reason = #{deleteReason}, deleted_by = #{requestUserId}, deleted_at = CURRENT_TIMESTAMP, request_id = #{requestId}, updated_at = CURRENT_TIMESTAMP, updated_by = #{requestUserId} where em.deleted_yn = 'N' and em.material_origin = 'BATCH_GENERATED' and em.material_status <> '평가확정'
and em.evaluation_year = #{criteria.normalizedEvaluationYear}
and em.area_code = #{criteria.normalizedAreaCode}
and em.generation_batch_id = #{criteria.normalizedGenerationBatchId}
